/**
 * Sample library for the design preview: species, facts and photos, no recordings yet.
 * The list lives in birds.json so the photo script can read it.
 * The real library (with audio, recordist and license) will come from ../../../birds.json,
 * generated by the audio pipeline.
 */
import { getLocales } from 'expo-localization';

import { dailyBird } from '@shared/daily';

import { AUDIO_FILES } from './audio-files';
import birdList from './birds.json';
import { LOOKALIKE_FILES } from './lookalike-files';
import lookalikeCredits from './lookalike-photos.json';
import { PHOTO_FILES } from './photo-files';
import photoCredits from './photos.json';
import recordingList from './recordings.json';

export interface LibraryBird {
  id: string;
  commonName: string;
  scientificName: string;
  regions: string[];
  fact: string;
  /** Common name of the bird's family, e.g. "Thrushes". */
  family?: string;
  /** Size compared with a sparrow, robin or crow. */
  size?: string;
  /** Where to look for it. */
  habitat?: string;
  /** What its song sounds like. */
  listen?: string;
  /** Two or three things that identify it at a glance. */
  marks?: string[];
  /** Birds it's often confused with, and how to tell them apart. */
  lookalikes?: { name: string; tell: string }[];
  /** How males, females and young birds differ, and any seasonal change. */
  plumage?: string;
  /** 12 characters, Jan to Dec: 2 = widespread, 1 = some, 0 = absent. Most of the US, or western Europe. */
  months?: string;
  seasonNote?: string;
  /** Where the common and scientific names come from. */
  nameNote?: string;
  /** Categories it falls under, e.g. "Songbird", "Thrush", "Feeder visitor". */
  groups?: string[];
}

export interface PhotoCredit {
  artist: string;
  license: string;
  source: string;
  file: string;
  /** Where the bird sits across the photo, 0 = left edge, 1 = right edge. Used to aim tall crops. */
  focusX?: number;
}

export const BIRDS: LibraryBird[] = birdList;
const credits: Record<string, PhotoCredit> = photoCredits;

/** The bird's photo (for <Image source>) and its credit, if one was downloaded. */
export function photoFor(id: string): { source: number; credit: PhotoCredit } | undefined {
  const source = PHOTO_FILES[id];
  const credit = credits[id];
  return source && credit ? { source, credit } : undefined;
}

/** Every photo credit, in library order, for the Credits screen. */
export const PHOTO_CREDITS = BIRDS.filter((b) => PHOTO_FILES[b.id] && credits[b.id]).map((b) => ({
  bird: b.commonName,
  ...credits[b.id]!,
}));

export const REGION_NAMES: Record<string, string> = {
  'north-america': 'North America',
  europe: 'Europe',
};

const NORTH_AMERICA = ['US', 'CA', 'MX'];
const EUROPE = ['GB', 'IE', 'FR', 'DE', 'ES', 'PT', 'IT', 'NL', 'BE', 'LU', 'CH', 'AT', 'DK', 'SE', 'NO', 'FI', 'IS',
  'PL', 'CZ', 'SK', 'HU', 'SI', 'HR', 'RO', 'BG', 'GR', 'EE', 'LV', 'LT', 'UA'];

function regionForCountry(country: string | null | undefined): string | undefined {
  if (!country) return undefined;
  const c = country.toUpperCase();
  if (NORTH_AMERICA.includes(c)) return 'north-america';
  if (EUROPE.includes(c)) return 'europe';
  return undefined;
}

/** Region from the device's language/region setting. No location permission involved. */
export function detectRegion(): string | undefined {
  try {
    for (const locale of getLocales()) {
      const region = regionForCountry(locale.regionCode);
      if (region) return region;
    }
  } catch {}
  try {
    const locale = Intl.DateTimeFormat().resolvedOptions().locale;
    return regionForCountry(locale.split(/[-_]/).find((p) => /^[A-Za-z]{2}$/.test(p) && p === p.toUpperCase()));
  } catch {}
  return undefined;
}

export function birdsFor(region: string | undefined, worldwide: boolean): LibraryBird[] {
  if (worldwide || !region) return BIRDS;
  const local = BIRDS.filter((b) => b.regions.includes(region));
  return local.length ? local : BIRDS;
}

export const birdById = (id: string | undefined) => BIRDS.find((b) => b.id === id);

export const birdByName = (name: string) => BIRDS.find((b) => b.commonName === name);

/** Other birds from the same family, out of the given list (the birds in your region by default). */
export const familyMates = (bird: LibraryBird, among: LibraryBird[] = BIRDS) =>
  bird.family ? among.filter((b) => b.family === bird.family && b.id !== bird.id) : [];

const lookalikeCreditMap: Record<string, PhotoCredit & { name: string }> = lookalikeCredits;
const slug = (name: string) => name.toLowerCase().replace(/'/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

/** A photo for a lookalike: the library photo if it's a library bird, otherwise its own small photo. */
export function lookalikePhoto(name: string): { source: number; credit: PhotoCredit } | undefined {
  const own = birdByName(name);
  if (own) return photoFor(own.id);
  const key = slug(name);
  const source = LOOKALIKE_FILES[key];
  const credit = lookalikeCreditMap[key];
  return source && credit ? { source, credit } : undefined;
}

/** Credits for the lookalike photos, for the Credits screen. */
export const LOOKALIKE_CREDITS = Object.values(lookalikeCreditMap).map((c) => ({ bird: c.name, ...c }));

/** A xeno-canto recording, trimmed into an alarm sound and an in-app playback file. */
export interface Recording {
  /** Exact filename AlarmKit plays, bundled into the iPhone app by plugins/with-alarm-sounds.js. */
  alarmFile: string;
  playbackFile: string;
  recordist: string;
  /** CC0, CC BY or CC BY-SA. */
  license: string;
  /** With version, e.g. "CC BY-SA 4.0". */
  licenseFull: string;
  xcNumber: string;
  sourceUrl: string;
  commonsUrl: string;
}
const recordings: Record<string, Recording> = recordingList;

/** The bird's recording and its playback file (for expo-audio), if it has one. */
export function recordingFor(id: string): (Recording & { source: number }) | undefined {
  const r = recordings[id];
  const source = AUDIO_FILES[id];
  return r && source ? { ...r, source } : undefined;
}

/** Every recording credit, in library order, for the Credits screen. */
export const RECORDING_CREDITS = BIRDS.filter((b) => recordings[b.id]).map((b) => ({ bird: b.commonName, ...recordings[b.id]! }));

/** "YYYY-MM-DD" for a moment, in the phone's own time zone. */
export function localDateKey(d: Date = new Date()): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

/**
 * The bird of the day for a date: the same for everyone with the same bird list (see
 * shared/src/daily.ts), skipping birds you've switched off.
 */
export function birdOfDay(localDate: string, library: LibraryBird[], blocked: readonly string[] = []): LibraryBird {
  const ids = library.map((b) => b.id);
  const off = new Set(blocked.length >= ids.length ? [] : blocked);
  return birdById(dailyBird(localDate, ids, off)) ?? library[0]!;
}
